type Tab = {
  value: string
  label: string
}

type Props = {
  tabs: Tab[]
  value: string
  onChange: (value: string) => void
  className?: string
}

export function ContextTabSwitcher({ tabs, value, onChange, className }: Props) {
  return (
    <div className={`inline-flex items-center bg-muted rounded-pill p-0.5 gap-0.5 ${className ?? ''}`}>
      {tabs.map((tab) => (
        <button
          key={tab.value}
          onClick={() => onChange(tab.value)}
          className={`px-4 py-1.5 text-sm font-medium rounded-pill transition-all ${
            value === tab.value
              ? 'bg-card text-foreground shadow-card'
              : 'text-muted-foreground hover:text-foreground'
          }`}
        >
          {tab.label}
        </button>
      ))}
    </div>
  )
}
